const msg = ($input.first().json.message?.text || '').trim();
const msgLower = msg.toLowerCase();
const chatId = $input.first().json.message?.chat?.id;

let intent = 'help';
let jobNumber = null;
let location = null;
let visaRequired = false;

if (msgLower.match(/find|search|list|show|jobs|latest|recent|digest|today/)) {
  intent = 'find_jobs';

  // Extract location -- "in New York", "near San Francisco", "in SF, CA"
  const locMatch = msgLower.match(/\b(?:in|near|around)\s+([a-zA-Z][a-zA-Z\s,]{2,40})(?:\s+(?:with|visa|sponsor|remote|onsite|hybrid|that|and)|[,.]|$)/i);
  if (locMatch) location = locMatch[1].trim().replace(/,\s*$/, '');

  // Remote overrides
  if (msgLower.match(/\bremote\b/)) location = 'Remote';

  // Visa sponsorship
  visaRequired = !!/\b(visa|h[- ]?1b?|sponsor)\b/.test(msgLower);

} else {
  const numMatch = msg.match(/^(\d+)$|apply.*?(\d+)/i);
  if (numMatch) {
    intent = 'apply';
    jobNumber = parseInt(numMatch[1] || numMatch[2]);
  }
}

return [{ json: { intent, jobNumber, chatId, raw_message: msg, location, visaRequired } }];

const staticData = $getWorkflowStaticData('global');
const companyOrder = staticData.companyOrder || [];
const location = staticData.searchLocation;
const visaRequired = staticData.searchVisaRequired;
const all = $input.all();

const keywords = [
  'engineer', 'scientist', 'ai', 'ml', 'machine learning', 'data',
  'research', 'llm', 'nlp', 'model', 'software', 'platform',
  'infrastructure', 'analytics', 'learning', 'intelligence', 'backend',
  'fullstack', 'full stack', 'developer', 'architect', 'devops', 'sre'
];

const allJobs = [];
all.forEach((item, idx) => {
  const company = companyOrder[idx] || 'Unknown';
  const jobs = item.json?.jobs || [];
  jobs.forEach(job => {
    const title = (job.title || '').toLowerCase();
    if (keywords.some(kw => title.includes(kw))) {
      allJobs.push({
        title: job.title,
        company: company,
        location: job.location?.name || 'Not specified',
        url: job.absolute_url || ''
      });
    }
  });
});

// Cap at 60 most relevant jobs -- LLM will score and filter
const selected = allJobs.slice(0, 60);

const jobsSummary = selected.map((j, i) =>
  `${i+1}. ${j.title} | ${j.company} | ${j.location} | ${j.url}`
).join('\n');

const meta = [
  location ? `LOCATION PREFERENCE: ${location} (within 100km, or Remote)` : '',
  visaRequired ? 'VISA FILTER: Only companies known to sponsor H-1B visas' : '',
].filter(Boolean).join('\n');

return [{ json: { jobs_summary: jobsSummary, total_found: selected.length, meta } }];

const staticData = $getWorkflowStaticData('global');
const chatId = staticData.searchChatId;
const location = staticData.searchLocation;
const visaRequired = staticData.searchVisaRequired;

let jobs = [];
try {
  const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  jobs = JSON.parse(cleaned).jobs || [];
} catch(e) { jobs = []; }

// Renumber, ensure score >= 7
jobs = jobs
  .filter(j => (j.score || 0) >= 7)
  .slice(0, 10)
  .map((j, i) => ({ ...j, number: i + 1 }));

staticData.jobs = jobs;

// Check diversity
const uniqueCompanies = new Set(jobs.map(j => j.company)).size;

if (jobs.length === 0) {
  const msg = location
    ? `❌ No jobs found near *${location}* with score ≥7. Try a different location or say "find me AI jobs" without a location filter.`
    : '❌ No qualifying jobs found right now. Try again for a fresh batch!';
  return [{ json: { chatId, table: msg } }];
}

// Build header
const companies = (staticData.companyOrder || []).join(', ');
let table = `🔍 *CareerForge Job Digest*\n`;
table += `_${jobs.length} jobs (≥7/10) from ${uniqueCompanies} companies_\n`;
if (location) table += `_📍 Filtered: near ${location}_\n`;
if (visaRequired) table += `_🛂 Visa sponsorship filter applied_\n`;
table += `_Searched: ${companies}_\n\n`;

jobs.forEach(j => {
  const score = j.score || 0;
  const dot = score >= 9 ? '🟢' : score >= 7 ? '🟡' : '🔴';
  const visa = visaRequired && j.visa_likely ? ' 🛂' : '';
  table += `*${j.number}.* ${j.title}\n`;
  table += `🏢 ${j.company} | 📍 ${j.location || 'N/A'} | ${dot} ${score}/10${visa}\n`;
  table += `💡 ${j.reason}\n`;
  if (j.url) table += `🔗 [Apply Here](${j.url})\n`;
  table += '\n';
});

const warning = jobs.length < 10 || uniqueCompanies < 5
  ? `_⚠️ Only ${jobs.length} qualifying jobs from ${uniqueCompanies} companies found. Say "find me AI jobs" again for a fresh batch._\n`
  : '';
table += warning;
table += '_Reply with a number to generate resume + cover letter!_';

return [{ json: { chatId, table } }];

const chatId = $input.first().json.chatId;
const jobNumber = $input.first().json.jobNumber || 1;

const staticData = $getWorkflowStaticData('global');
const jobs = staticData.jobs || [];
const job = jobs.find(j => j.number === jobNumber);

if (!job) {
  return [{ json: {
    chatId,
    error: true,
    error_msg: 'Job #' + jobNumber + ' not found. Search first by saying *find me AI jobs*.'
  } }];
}

// Store for retrieval after HTTP calls lose context
staticData.currentJob = job;
staticData.applyChatId = chatId;

const resumeText = 'YOUR FULL NAME | your.email@example.com | Your City, State | yoursite.com

SUMMARY
Replace this with your own master resume text, or fetch it from Supabase.

EXPERIENCE
Job Title -- Company, Location (Start -- End)
- Key achievement with metrics
- Key achievement with metrics

SKILLS
Add your technical skills here

EDUCATION
Degree -- University (Year)';

return [{ json: {
  chatId,
  error: false,
  job_title: job.title,
  job_company: job.company,
  job_location: job.location,
  job_context: job.reason,
  resume_text: resumeText
} }];

const staticData = $getWorkflowStaticData('global');
const job = staticData.currentJob;
const chatId = staticData.applyChatId;

let bullets = [];
let keywords = [];
try {
  const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);
