  keywords = [];
}

// Store for Format node to retrieve after CoverForge HTTP call
staticData.resumeBullets = bullets;
staticData.resumeKeywords = keywords;

return [{ json: {
  chatId,
  job_title: job?.title || '',
  job_company: job?.company || '',
  job_context: job?.reason || ''
} }];

const staticData = $getWorkflowStaticData('global');
const chatId = staticData.applyChatId;
const job = staticData.currentJob;
const bullets = staticData.resumeBullets || [];
const keywords = staticData.resumeKeywords || [];

let coverLetter = '';
try {
  const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  coverLetter = JSON.parse(cleaned).cover_letter || 'Cover letter generation failed.';
} catch(e) {
  coverLetter = 'Cover letter generation failed. Please retry.';
}

let msg = '\u2705 *Application Package Ready!*\n\n';
msg += '*' + (job?.title || 'Role') + '* @ *' + (job?.company || 'Company') + '*\n\n';
msg += '\uD83D\uDCC4 *Tailored Resume Bullets:*\n';
bullets.forEach(b => { msg += '\u2022 ' + b + '\n'; });
if (keywords.length > 0) {
  msg += '\n\uD83D\uDD11 *Keywords Added:* ' + keywords.slice(0, 5).join(', ') + '\n';
}
msg += '\n\u2709\uFE0F *Cover Letter:*\n' + coverLetter + '\n\n';
msg += '_Search again anytime! Say *find me AI jobs* for a fresh digest._';

return [{ json: { chatId, message: msg } }];

