// Fisher-Yates shuffle
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Pick 10 random companies every run
const selected = shuffle(ALL_COMPANIES).slice(0, 10);
staticData.companyOrder = selected.map(c => c.name);

return selected.map(c => ({
  json: { url: `https://boards-api.greenhouse.io/v1/boards/${c.slug}/jobs`, company: c.name, slug: c.slug }
}));
